import type { LogEntry } from "./parse.ts";

/**
 * Count requests per HTTP status code.
 *
 * Returns a plain object mapping status code to request count, with keys in
 * ascending numeric order so the breakdown reads 200, 301, 404, 500, ...
 */
export function countByStatus(entries: LogEntry[]): Record<number, number> {
	const counts = new Map<number, number>();
	for (const e of entries) counts.set(e.status, (counts.get(e.status) ?? 0) + 1);
	return Object.fromEntries([...counts.entries()].sort((a, b) => a[0] - b[0]));
}

/**
 * Count requests per request path.
 *
 * Returns a plain object mapping path to request count, ordered by request
 * count (descending) with ties broken by path (ascending) so the busiest
 * paths come first, deterministically.
 */
export function countByPath(entries: LogEntry[]): Record<string, number> {
	const counts = new Map<string, number>();
	for (const e of entries) counts.set(e.path, (counts.get(e.path) ?? 0) + 1);
	return Object.fromEntries(
		[...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
	);
}
```

