import type { LogEntry } from "./parse.ts";

/**
 * Count requests per HTTP status code.
 *
 * Returns a plain object mapping status code to request count, with keys in
 * ascending numeric order so a breakdown reads 200, 301, 404, 500, ...
 *
 * Example:
 *   { 200: 42, 404: 3, 500: 1 }
 */
export function countByStatus(entries: LogEntry[]): Record<number, number> {
	const counts = new Map<number, number>();
	for (const e of entries) counts.set(e.status, (counts.get(e.status) ?? 0) + 1);
	return Object.fromEntries([...counts.entries()].sort((a, b) => a[0] - b[0]));
}

/**
 * Count requests per request path.
 *
 * Returns a plain object mapping path to request count, ordered by request
 * count (descending) with ties broken by path (ascending), so the busiest
 * paths come first, deterministically.
 *
 * Example:
 *   { "/": 40, "/api/users": 7, "/img/logo.png": 7 }
 */
export function countByPath(entries: LogEntry[]): Record<string, number> {
	const counts = new Map<string, number>();
	for (const e of entries) counts.set(e.path, (counts.get(e.path) ?? 0) + 1);
	return Object.fromEntries(
		[...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
	);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import type { LogEntry } from "../src/parse.ts";
import { countByStatus, countByPath } from "../src/stats.ts";

/** Build a LogEntry with sensible defaults, overriding the given fields. */
function entry(overrides: Partial<LogEntry> = {}): LogEntry {
	return {
		ip: "127.0.0.1",
		time: "10/Oct/2000:13:55:36 -0700",
		method: "GET",
		path: "/",
		status: 200,
		bytes: 0,
		...overrides,
	};
}

test("countByStatus counts requests per status code", () => {
	const entries = [
		entry({ status: 200, path: "/a" }),
		entry({ status: 200, path: "/b" }),
		entry({ status: 404, path: "/c" }),
		entry({ status: 200, path: "/a" }),
		entry({ status: 500, path: "/d" }),
	];
	assert.deepEqual(countByStatus(entries), { 200: 3, 404: 1, 500: 1 });
});

test("countByStatus orders status codes in ascending order", () => {
	const entries = [entry({ status: 500 }), entry({ status: 200 }), entry({ status: 404 })];
	assert.deepEqual(Object.keys(countByStatus(entries)), ["200", "404", "500"]);
});

test("countByStatus returns an empty object for no entries", () => {
	assert.deepEqual(countByStatus([]), {});
});

test("countByPath counts requests per path", () => {
	const entries = [
		entry({ path: "/a" }),
		entry({ path: "/b" }),
		entry({ path: "/b" }),
		entry({ path: "/a" }),
		entry({ path: "/c" }),
	];
	assert.deepEqual(countByPath(entries), { "/a": 2, "/b": 2, "/c": 1 });
});

test("countByPath orders by count (desc), then path (asc) on ties", () => {
	const entries = [
		entry({ path: "/c" }),
		entry({ path: "/b" }),
		entry({ path: "/a" }),
		entry({ path: "/b" }),
	];
	assert.deepEqual(countByPath(entries), { "/b": 2, "/a": 1, "/c": 1 });
	assert.deepEqual(Object.keys(countByPath(entries)), ["/b", "/a", "/c"]);
});

test("countByPath returns an empty object for no entries", () => {
	assert.deepEqual(countByPath([]), {});
});

