/**
 * Parser for the Common Log Format (CLF) used by many web servers.
 *
 * Example line:
 *   127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 1234
 *
 * The `ident`, `user`, and protocol fields are intentionally dropped: logstat
 * only needs the fields below to summarize traffic.
 */

export interface LogEntry {
	/** Client IP address (the `host` field). */
	ip: string;
	/** Raw request timestamp, e.g. `10/Oct/2000:13:55:36 -0700`. */
	time: string;
	/** HTTP method, e.g. `GET`. */
	method: string;
	/** Request path, e.g. `/apache_pb.gif`. */
	path: string;
	/** HTTP status code, e.g. `200`. */
	status: number;
	/** Response size in bytes; `0` when the log recorded `-`. */
	bytes: number;
}

/**
 * Matches a CLF line:
 *   <ip> <ident> <user> [<time>] "<method> <path> [protocol]" <status> <bytes>
 *
 * `ident`/`user` are skipped (groups 2–3), and the optional protocol after the
 * path is ignored. `bytes` is a number or `-`.
 */
const CLF =
	/^(\S+) \S+ \S+ \[([^\]]+)\] "(\S+) (\S+)(?: [^"]*)?" (\d{3}) (\d+|-)\s*$/;

/**
 * Parse a single CLF line.
 *
 * Returns a {@link LogEntry} on success, or `null` when the line does not
 * match the expected shape (e.g. blank lines or malformed entries), so callers
 * can skip them without throwing.
 */
export function parse(line: string): LogEntry | null {
	const m = CLF.exec(line);
	if (!m) return null;
	const [, ip, time, method, path, status, bytes] = m;
	return {
		ip,
		time,
		method,
		path,
		status: Number(status),
		bytes: bytes === "-" ? 0 : Number(bytes),
	};
}

import type { LogEntry } from "./parse.ts";

/**
 * Count requests per HTTP status code.
 *
 * Returns a plain object mapping status code to request count, with keys in
 * ascending numeric order so a breakdown reads 200, 301, 404, 500, ...
 *
 * Example:
 *   { 200: 42, 404: 3, 500: 1 }
 */
export function countByStatus(entries: LogEntry[]): Record<number, number> {
	const counts = new Map<number, number>();
	for (const e of entries) counts.set(e.status, (counts.get(e.status) ?? 0) + 1);
	return Object.fromEntries([...counts.entries()].sort((a, b) => a[0] - b[0]));
}

/**
 * Count requests per request path.
 *
 * Returns a plain object mapping path to request count, ordered by request
 * count (descending) with ties broken by path (ascending), so the busiest
 * paths come first, deterministically.
 *
 * Example:
 *   { "/": 40, "/api/users": 7, "/img/logo.png": 7 }
 */
export function countByPath(entries: LogEntry[]): Record<string, number> {
	const counts = new Map<string, number>();
	for (const e of entries) counts.set(e.path, (counts.get(e.path) ?? 0) + 1);
	return Object.fromEntries(
		[...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
	);
}

