#!/usr/bin/env node
/**
 * Generate a large, deterministic Common Log Format fixture.
 *
 * Writes fixtures/big.log with 100,000 CLF lines drawn from a seeded PRNG.
 * Because the seed is fixed, every run produces a byte-identical file — handy
 * for tests and for diffing output across runs.
 *
 * The distribution is intentionally skewed so `--top N` is meaningful: a
 * Zipf-weighted set of "hot" base paths (clear top-N leaders) plus a small
 * share of near-unique long-tail paths, a range of status codes (200-heavy),
 * and response sizes that are usually small and occasionally large.
 *
 * Usage: node scripts/gen.ts   (or: npm run gen)
 */

import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// --- Config (fixed → deterministic) ----------------------------------------
const SEED = 0x5eed;
const LINES = 100_000;

// --- Seeded PRNG (mulberry32): fast, fully deterministic per 32-bit seed ----
function mulberry32(seed: number): () => number {
	let a = seed >>> 0;
	return () => {
		let t = (a += 0x6d2b79f5) | 0;
		t = Math.imul(t ^ (t >>> 15), t | 1);
		t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
		return ((t ^ (t >>> 14)) >>> 0) / 0x100000000;
	};
}
const rand = mulberry32(SEED);
const randInt = (min: number, max: number): number =>
	min + Math.floor(rand() * (max - min + 1));
const pick = <T>(arr: readonly T[]): T => arr[Math.floor(rand() * arr.length)];

// --- Value pools ------------------------------------------------------------
// Base paths, Zipf-weighted by index (index 0 is the hottest). This produces
// a clear ranking so `--top N` surfaces the most frequent paths.
const BASE_PATHS = [
	"/",
	"/index.html",
	"/api/orders",
	"/api/users",
	"/products",
	"/search",
	"/cart",
	"/checkout",
	"/login",
	"/about",
	"/blog",
	"/docs",
	"/images/logo.png",
	"/css/site.css",
	"/js/app.js",
	"/assets/bundle.js",
	"/assets/main.css",
	"/favicon.ico",
	"/robots.txt",
	"/sitemap.xml",
	"/healthz",
	"/metrics",
] as const;

// GET-heavy, like a real web log.
const METHODS = [
	"GET",
	"GET",
	"GET",
	"GET",
	"POST",
	"PUT",
	"DELETE",
	"HEAD",
	"OPTIONS",
] as const;

// 200-heavy, but covers redirects and common errors too.
const STATUSES = [
	200, 200, 200, 200, 200, 200, 200, 200, 200, 200,
	200, 200, 200, 200, 200, 200, 200, 200, 200, 200,
	201, 204,
	301, 302, 304,
	400, 401, 403, 404, 404, 405,
	500, 502, 503,
] as const;

const LONG_TAIL_KINDS = ["item", "article", "download", "page"] as const;

const pathWeights = BASE_PATHS.map((_, i) => 1 / (i + 1));
const pathTotal = pathWeights.reduce((sum, w) => sum + w, 0);

function pickPath(): string {
	// ~5% long tail: a near-unique resource, so most of these are one-offs.
	if (rand() < 0.05) {
		const kind = pick(LONG_TAIL_KINDS);
		return `/${kind}/${randInt(1, 99_999)}`;
	}
	// Otherwise a base path, Zipf-weighted (index 0 hottest).
	let x = rand() * pathTotal;
	for (let i = 0; i < pathWeights.length; i++) {
		x -= pathWeights[i];
		if (x <= 0) return BASE_PATHS[i];
	}
	return BASE_PATHS[BASE_PATHS.length - 1];
}

function randomIp(): string {
	return `${randInt(1, 254)}.${randInt(0, 255)}.${randInt(0, 255)}.${randInt(1, 254)}`;
}

// Skewed small: most responses are small, a few are large.
function randomBytes(status: number): string {
	if (status === 304) return "-"; // Not Modified → no body
	if (rand() < 0.02) return "-"; // occasionally empty/unknown
	return String(Math.floor(Math.pow(rand(), 2.5) * 200_000));
}

// --- Timestamps (UTC getters → identical across machines/timezones) ---------
const MONTHS = [
	"Jan", "Feb", "Mar", "Apr", "May", "Jun",
	"Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
] as const;
const START = Date.UTC(2024, 0, 1) / 1000; // fixed epoch, seconds

function formatTime(epochSec: number): string {
	const d = new Date(epochSec * 1000);
	const pad = (n: number) => String(n).padStart(2, "0");
	return (
		`${d.getUTCDate()}/${MONTHS[d.getUTCMonth()]}/${d.getUTCFullYear()}:` +
		`${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())} +0000`
	);
}

// --- Generate ---------------------------------------------------------------
const here = dirname(fileURLToPath(import.meta.url));
const OUTPUT = join(here, "..", "fixtures", "big.log");

const lines = new Array<string>(LINES);
let t = START;
for (let i = 0; i < LINES; i++) {
	t += randInt(0, 2); // roughly chronological
	const status = pick(STATUSES);
	lines[i] =
		`${randomIp()} - - [${formatTime(t)}] ` +
		`"${pick(METHODS)} ${pickPath()} HTTP/1.1" ${status} ${randomBytes(status)}`;
}

const output = lines.join("\n") + "\n";
writeFileSync(OUTPUT, output);
console.log(`wrote ${LINES} lines to ${OUTPUT} (${output.length} chars)`);

