/**
 * Parser for the Common Log Format (CLF) used by many web servers.
 *
 * Example line:
 *   127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 1234
 *
 * The `ident`, `user`, and protocol fields are intentionally dropped: logstat
 * only needs the fields below to summarize traffic.
 */

export interface LogEntry {
	/** Client IP address (the `host` field). */
	ip: string;
	/** Raw request timestamp, e.g. `10/Oct/2000:13:55:36 -0700`. */
	time: string;
	/** HTTP method, e.g. `GET`. */
	method: string;
	/** Request path, e.g. `/apache_pb.gif`. */
	path: string;
	/** HTTP status code, e.g. `200`. */
	status: number;
	/** Response size in bytes; `0` when the log recorded `-`. */
	bytes: number;
}

/**
 * Matches a CLF line:
 *   <ip> <ident> <user> [<time>] "<method> <path> [protocol]" <status> <bytes>
 *
 * `ident`/`user` are skipped (groups 2–3), and the optional protocol after the
 * path is ignored. `bytes` is a number or `-`.
 */
const CLF =
	/^(\S+) \S+ \S+ \[([^\]]+)\] "(\S+) (\S+)(?: [^"]*)?" (\d{3}) (\d+|-)\s*$/;

/**
 * Parse a single CLF line.
 *
 * Returns a {@link LogEntry} on success, or `null` when the line does not
 * match the expected shape (e.g. blank lines or malformed entries), so callers
 * can skip them without throwing.
 */
export function parse(line: string): LogEntry | null {
	const m = CLF.exec(line);
	if (!m) return null;
	const [, ip, time, method, path, status, bytes] = m;
	return {
		ip,
		time,
		method,
		path,
		status: Number(status),
		bytes: bytes === "-" ? 0 : Number(bytes),
	};
}

#!/usr/bin/env node
/**
 * logstat command-line entry point.
 *
 * Reads a Common Log Format access log and prints the per-status and per-path
 * request counts as JSON on stdout.
 *
 * Usage:
 *   node src/cli.ts [--top N] <access.log>
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { parse } from "./parse.ts";
import type { LogEntry } from "./parse.ts";
import { countByStatus, countByPath } from "./stats.ts";

export interface ParsedArgs {
	/** Path to the access log, or `null` when none was given. */
	file: string | null;
	/** Max number of paths to keep, or `null` when `--top` was not given. */
	top: number | null;
	/** Usage-error message, or `null` when the arguments are valid. */
	error: string | null;
}

/**
 * Parse `logstat` arguments (everything after the script name).
 *
 * `--top` may appear before or after the positional file argument. Returns a
 * {@link ParsedArgs} with `error` set on the first problem, without throwing.
 */
export function parseArgs(argv: string[]): ParsedArgs {
	const result: ParsedArgs = { file: null, top: null, error: null };
	for (let i = 0; i < argv.length; i++) {
		const arg = argv[i];
		if (arg === "--top") {
			const value = argv[++i];
			if (value === undefined) {
				result.error = "--top requires a value";
				return result;
			}
			const n = Number(value);
			if (!Number.isInteger(n) || n < 0) {
				result.error = `--top expects a non-negative integer, got "${value}"`;
				return result;
			}
			result.top = n;
		} else if (arg.startsWith("--")) {
			result.error = `unknown option "${arg}"`;
			return result;
		} else if (result.file === null) {
			result.file = arg;
		} else {
			result.error = `unexpected argument "${arg}"`;
			return result;
		}
	}
	return result;
}

export interface Summary {
	/** Request counts per HTTP status code. */
	status: Record<number, number>;
	/** Request counts per path (optionally trimmed to the top N). */
	path: Record<string, number>;
}

/**
 * Build the summary from parsed entries.
 *
 * When `top` is not `null`, `path` is trimmed to the `top` most frequent
 * paths, relying on {@link countByPath}'s count-descending order.
 */
export function summarize(entries: LogEntry[], top: number | null): Summary {
	let path = countByPath(entries);
	if (top !== null) path = Object.fromEntries(Object.entries(path).slice(0, top));
	return { status: countByStatus(entries), path };
}

function main(): void {
	const { file, top, error } = parseArgs(process.argv.slice(2));
	if (error) {
		process.stderr.write(`logstat: ${error}\n`);
		process.exitCode = 1;
		return;
	}
	if (file === null) {
		process.stderr.write("usage: node src/cli.ts [--top N] <access.log>\n");
		process.exitCode = 1;
		return;
	}

	let raw: string;
	try {
		raw = readFileSync(file, "utf8");
	} catch (err) {
		process.stderr.write(`logstat: cannot read ${file}: ${(err as Error).message}\n`);
		process.exitCode = 1;
		return;
	}

	const entries = raw
		.split("\n")
		.map(parse)
		.filter((e): e is LogEntry => e !== null);

	process.stdout.write(`${JSON.stringify(summarize(entries, top), null, 2)}\n`);
}

// Run only when executed directly (not when imported, e.g. by tests).
if (process.argv[1] === fileURLToPath(import.meta.url)) main();

import { test } from "node:test";
import { strict as assert } from "node:assert";
import { parseArgs, summarize } from "../src/cli.ts";
import type { LogEntry } from "../src/parse.ts";

// --- parseArgs ---

test("parseArgs: file only", () => {
	assert.deepEqual(parseArgs(["access.log"]), { file: "access.log", top: null, error: null });
});

test("parseArgs: --top before the file", () => {
	assert.deepEqual(parseArgs(["--top", "3", "access.log"]), {
		file: "access.log",
		top: 3,
		error: null,
	});
});

test("parseArgs: --top after the file", () => {
	assert.deepEqual(parseArgs(["access.log", "--top", "3"]), {
		file: "access.log",
		top: 3,
		error: null,
	});
});

test("parseArgs: --top 0 is a valid value", () => {
	assert.deepEqual(parseArgs(["--top", "0", "access.log"]), {
		file: "access.log",
		top: 0,
		error: null,
	});
});

test("parseArgs: no arguments is not an error", () => {
	assert.deepEqual(parseArgs([]), { file: null, top: null, error: null });
});

test("parseArgs: --top without a value", () => {
	assert.equal(parseArgs(["--top"]).error, "--top requires a value");
});

test("parseArgs: --top with a non-integer", () => {
	assert.equal(
		parseArgs(["--top", "abc", "access.log"]).error,
		'--top expects a non-negative integer, got "abc"',
	);
});

test("parseArgs: --top with a negative number", () => {
	assert.equal(
		parseArgs(["--top", "-1", "access.log"]).error,
		'--top expects a non-negative integer, got "-1"',
	);
});

test("parseArgs: unknown option", () => {
	assert.equal(parseArgs(["--bogus"]).error, 'unknown option "--bogus"');
});

test("parseArgs: more than one positional", () => {
	assert.equal(parseArgs(["a.log", "b.log"]).error, 'unexpected argument "b.log"');
});

// --- summarize ---

const entries: LogEntry[] = [
	{ ip: "1.1.1.1", time: "t", method: "GET", path: "/a", status: 200, bytes: 1 },
	{ ip: "1.1.1.1", time: "t", method: "GET", path: "/b", status: 200, bytes: 1 },
	{ ip: "1.1.1.1", time: "t", method: "GET", path: "/a", status: 404, bytes: 1 },
	{ ip: "1.1.1.1", time: "t", method: "GET", path: "/c", status: 200, bytes: 1 },
];

test("summarize: keeps all paths when top is null", () => {
	assert.deepEqual(summarize(entries, null), {
		status: { 200: 3, 404: 1 },
		path: { "/a": 2, "/b": 1, "/c": 1 },
	});
});

test("summarize: trims paths to the top N", () => {
	assert.deepEqual(summarize(entries, 1).path, { "/a": 2 });
});

test("summarize: top larger than the distinct paths keeps all", () => {
	assert.deepEqual(summarize(entries, 10).path, { "/a": 2, "/b": 1, "/c": 1 });
});

test("summarize: top 0 yields no paths", () => {
	assert.deepEqual(summarize(entries, 0).path, {});
});

test("summarize: status counts are unaffected by top", () => {
	assert.deepEqual(summarize(entries, 1).status, { 200: 3, 404: 1 });
});

