/**
 * Parser for the Common Log Format (CLF) used by many web servers.
 *
 * Example line:
 *   127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 1234
 *
 * The `ident`, `user`, and protocol fields are intentionally dropped: logstat
 * only needs the fields below to summarize traffic.
 */

export interface LogEntry {
	/** Client IP address (the `host` field). */
	ip: string;
	/** Raw request timestamp, e.g. `10/Oct/2000:13:55:36 -0700`. */
	time: string;
	/** HTTP method, e.g. `GET`. */
	method: string;
	/** Request path, e.g. `/apache_pb.gif`. */
	path: string;
	/** HTTP status code, e.g. `200`. */
	status: number;
	/** Response size in bytes; `0` when the log recorded `-`. */
	bytes: number;
}

/**
 * Matches a CLF line:
 *   <ip> <ident> <user> [<time>] "<method> <path> [protocol]" <status> <bytes>
 *
 * `ident`/`user` are skipped (groups 2–3), and the optional protocol after the
 * path is ignored. `bytes` is a number or `-`.
 */
const CLF =
	/^(\S+) \S+ \S+ \[([^\]]+)\] "(\S+) (\S+)(?: [^"]*)?" (\d{3}) (\d+|-)\s*$/;

/**
 * Parse a single CLF line.
 *
 * Returns a {@link LogEntry} on success, or `null` when the line does not
 * match the expected shape (e.g. blank lines or malformed entries), so callers
 * can skip them without throwing.
 */
export function parse(line: string): LogEntry | null {
	const m = CLF.exec(line);
	if (!m) return null;
	const [, ip, time, method, path, status, bytes] = m;
	return {
		ip,
		time,
		method,
		path,
		status: Number(status),
		bytes: bytes === "-" ? 0 : Number(bytes),
	};
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { parse } from "../src/parse.ts";

test("parses a well-formed common log format line", () => {
	const line =
		'127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 1234';
	assert.deepEqual(parse(line), {
		ip: "127.0.0.1",
		time: "10/Oct/2000:13:55:36 -0700",
		method: "GET",
		path: "/apache_pb.gif",
		status: 200,
		bytes: 1234,
	});
});

test("treats a dash for bytes as zero", () => {
	const line =
		'203.0.113.9 - - [10/Oct/2000:13:55:36 -0700] "HEAD / HTTP/1.1" 304 -';
	const entry = parse(line);
	assert.equal(entry?.bytes, 0);
	assert.equal(entry?.status, 304);
	assert.equal(entry?.method, "HEAD");
	assert.equal(entry?.path, "/");
});

test("keeps the raw timestamp and handles a query string in the path", () => {
	const line =
		'2001:db8::1 - - [01/Jan/2024:00:00:00 +0000] "GET /search?q=hello HTTP/1.1" 200 512';
	const entry = parse(line);
	assert.equal(entry?.ip, "2001:db8::1");
	assert.equal(entry?.time, "01/Jan/2024:00:00:00 +0000");
	assert.equal(entry?.path, "/search?q=hello");
});

test("returns null for malformed lines", () => {
	assert.equal(parse(""), null);
	assert.equal(parse("not a log line"), null);
	// Missing the quoted request.
	assert.equal(parse('127.0.0.1 - - [10/Oct/2000:13:55:36 -0700] 200 1234'), null);
});

import { test } from "node:test";
import { strict as assert } from "node:assert";
import { parseArgs, parseLines, summarize } from "../src/cli.ts";
import type { LogEntry } from "../src/parse.ts";

// --- parseArgs ---

test("parseArgs: file only", () => {
	assert.deepEqual(parseArgs(["access.log"]), { file: "access.log", top: null, error: null });
});

test("parseArgs: --top before the file", () => {
	assert.deepEqual(parseArgs(["--top", "3", "access.log"]), {
		file: "access.log",
		top: 3,
		error: null,
	});
});

test("parseArgs: --top after the file", () => {
	assert.deepEqual(parseArgs(["access.log", "--top", "3"]), {
		file: "access.log",
		top: 3,
		error: null,
	});
});

test("parseArgs: --top 0 is a valid value", () => {
	assert.deepEqual(parseArgs(["--top", "0", "access.log"]), {
		file: "access.log",
		top: 0,
		error: null,
	});
});

test("parseArgs: no arguments is not an error", () => {
	assert.deepEqual(parseArgs([]), { file: null, top: null, error: null });
});

test("parseArgs: --top without a value", () => {
	assert.equal(parseArgs(["--top"]).error, "--top requires a value");
