/**
 * Two-letter (actually three-letter) month abbreviation → month number (1–12),
 * for parsing CLF timestamps.
 */
const CLF_MONTHS: Record<string, number> = {
	Jan: 1, Feb: 2, Mar: 3, Apr: 4, May: 5, Jun: 6,
	Jul: 7, Aug: 8, Sep: 9, Oct: 10, Nov: 11, Dec: 12,
};

const CLF_TIME =
	/^(\d{1,2})\/([A-Za-z]{3})\/(\d{4}):(\d{2}):(\d{2}):(\d{2}) ([+-])(\d{2})(\d{2})$/;

/**
 * Convert a CLF timestamp such as `10/Oct/2000:13:55:36 -0700` to epoch
 * milliseconds, honoring the embedded UTC offset. Returns `null` when the
 * string is not a valid CLF timestamp.
 */
export function clfTimeToMs(time: string): number | null {
	const m = CLF_TIME.exec(time);
	if (!m) return null;
	const [, day, mon, year, hh, mm, ss, tzSign, tzH, tzM] = m;
	const month = CLF_MONTHS[mon];
	if (!month) return null;
	const iso = `${year}-${String(month).padStart(2, "0")}-${day.padStart(2, "0")}T${hh}:${mm}:${ss}${tzSign}${tzH}:${tzM}`;
	const ms = Date.parse(iso);
	return Number.isNaN(ms) ? null : ms;
}
```

