	assert.equal(parse(""), null);
	assert.equal(parse("not a log line"), null);
	// Missing the quoted request.
	assert.equal(parse('127.0.0.1 - - [10/Oct/2000:13:55:36 -0700] 200 1234'), null);
});

// --- clfTimeToMs ---

test("clfTimeToMs converts a CLF timestamp to epoch milliseconds", () => {
	// 10/Oct/2000:13:55:36 -0700 is 20:55:36 UTC.
	assert.equal(
		clfTimeToMs("10/Oct/2000:13:55:36 -0700"),
		Date.UTC(2000, 9, 10, 20, 55, 36),
	);
});

test("clfTimeToMs honors positive and negative UTC offsets", () => {
	assert.equal(clfTimeToMs("01/Jan/2024:00:00:00 +0000"), Date.UTC(2024, 0, 1, 0, 0, 0));
	assert.equal(clfTimeToMs("15/Mar/2024:12:00:00 +0200"), Date.UTC(2024, 2, 15, 10, 0, 0));
	assert.equal(clfTimeToMs("15/Mar/2024:12:00:00 -0500"), Date.UTC(2024, 2, 15, 17, 0, 0));
});

test("clfTimeToMs returns null for malformed input", () => {
	assert.equal(clfTimeToMs("garbage"), null);
	assert.equal(clfTimeToMs("10/Oct/2000 13:55:36"), null); // missing time/tz
	assert.equal(clfTimeToMs(""), null);
});

