	const kept = filterSince(
		[at("09/Jan/2024:23:59:59 +0000", "/before"), at("10/Jan/2024:00:00:00 +0000", "/exactly")],
		cutoff,
	);
	assert.deepEqual(
		kept.map((e) => e.path),
		["/exactly"],
	);
});

test("filterSince: empty input yields empty output", () => {
	assert.deepEqual(filterSince([], Date.parse("2024-01-01")), []);
});
```

