#!/usr/bin/env node
/**
 * logstat command-line entry point.
 *
 * Reads a Common Log Format access log and prints the per-status and per-path
 * request counts, plus how many malformed lines were skipped, as JSON on
 * stdout.
 *
 * Usage:
 *   node --experimental-strip-types src/cli.ts [--top N] [--since <ISO date>] <access.log>
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { parse, clfTimeToMs } from "./parse.ts";
import type { LogEntry } from "./parse.ts";
import { countByStatus, countByPath } from "./stats.ts";

export interface ParsedArgs {
	/** Path to the access log, or `null` when none was given. */
	file: string | null;
	/** Max number of paths to keep, or `null` when `--top` was not given. */
	top: number | null;
	/** The raw `--since` ISO date, or `null` when not given. */
	since: string | null;
	/** Usage-error message, or `null` when the arguments are valid. */
	error: string | null;
}

/**
 * Parse `logstat` arguments (everything after the script name).
 *
 * `--top` may appear before or after the positional file argument. Returns a
 * {@link ParsedArgs} with `error` set on the first problem, without throwing.
 */
export function parseArgs(argv: string[]): ParsedArgs {
	const result: ParsedArgs = { file: null, top: null, since: null, error: null };
	for (let i = 0; i < argv.length; i++) {
		const arg = argv[i];
		if (arg === "--top") {
			const value = argv[++i];
			if (value === undefined) {
				result.error = "--top requires a value";
				return result;
			}
			const n = Number(value);
			if (!Number.isInteger(n) || n < 0) {
				result.error = `--top expects a non-negative integer, got "${value}"`;
				return result;
			}
			result.top = n;
		} else if (arg === "--since") {
			const value = argv[++i];
			if (value === undefined) {
				result.error = "--since requires a value";
				return result;
			}
			if (Number.isNaN(Date.parse(value))) {
				result.error = `--since expects an ISO date, got "${value}"`;
				return result;
			}
			result.since = value;
		} else if (arg.startsWith("--")) {
			result.error = `unknown option "${arg}"`;
			return result;
		} else if (result.file === null) {
			result.file = arg;
		} else {
			result.error = `unexpected argument "${arg}"`;
			return result;
		}
	}
	return result;
}

export interface Summary {
	/** Request counts per HTTP status code. */
	status: Record<number, number>;
	/** Request counts per path (optionally trimmed to the top N). */
	path: Record<string, number>;
}

/**
 * Build the summary from parsed entries.
 *
 * When `top` is not `null`, `path` is trimmed to the `top` most frequent
 * paths, relying on {@link countByPath}'s count-descending order.
 */
export function summarize(entries: LogEntry[], top: number | null): Summary {
	let path = countByPath(entries);
	if (top !== null) path = Object.fromEntries(Object.entries(path).slice(0, top));
	return { status: countByStatus(entries), path };
}

/**
 * Keep only the entries whose CLF timestamp is at or after `sinceMs`
 * (epoch milliseconds). Used to implement `--since`.
 */
export function filterSince(entries: LogEntry[], sinceMs: number): LogEntry[] {
	return entries.filter((e) => {
		const ms = clfTimeToMs(e.time);
		return ms !== null && ms >= sinceMs;
	});
}

/**
 * Parse many raw log lines into entries.
 *
 * Blank lines are ignored. Non-blank lines that {@link parse} cannot match are
 * skipped and counted in `skipped`, so a few malformed lines in the middle of
 * a log never abort the run.
 */
export function parseLines(lines: string[]): { entries: LogEntry[]; skipped: number } {
	const entries: LogEntry[] = [];
	let skipped = 0;
	for (const line of lines) {
		if (line.trim() === "") continue;
		const entry = parse(line);
		if (entry === null) skipped++;
		else entries.push(entry);
	}
	return { entries, skipped };
}

function main(): void {
	const { file, top, since, error } = parseArgs(process.argv.slice(2));
	if (error) {
		process.stderr.write(`logstat: ${error}\n`);
		process.exitCode = 1;
		return;
	}
	if (file === null) {
		process.stderr.write("usage: node --experimental-strip-types src/cli.ts [--top N] [--since <ISO date>] <access.log>\n");
		process.exitCode = 1;
		return;
	}

	let raw: string;
	try {
		raw = readFileSync(file, "utf8");
	} catch (err) {
		process.stderr.write(`logstat: cannot read ${file}: ${(err as Error).message}\n`);
		process.exitCode = 1;
		return;
	}

	const parsed = parseLines(raw.split("\n"));
	const skipped = parsed.skipped;
	let entries = parsed.entries;
	if (since !== null) {
		entries = filterSince(entries, Date.parse(since));
	}
	const summary = summarize(entries, top);
	const output = { status: summary.status, path: summary.path, skipped };
	process.stdout.write(`${JSON.stringify(output, null, 2)}\n`);
}

// Run only when executed directly (not when imported, e.g. by tests).
if (process.argv[1] === fileURLToPath(import.meta.url)) main();

/**
 * Parser for the Common Log Format (CLF) used by many web servers.
 *
 * Example line:
 *   127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 1234
 *
 * The `ident`, `user`, and protocol fields are intentionally dropped: logstat
 * only needs the fields below to summarize traffic.
 */

export interface LogEntry {
	/** Client IP address (the `host` field). */
	ip: string;
	/** Raw request timestamp, e.g. `10/Oct/2000:13:55:36 -0700`. */
	time: string;
	/** HTTP method, e.g. `GET`. */
	method: string;
	/** Request path, e.g. `/apache_pb.gif`. */
	path: string;
	/** HTTP status code, e.g. `200`. */
	status: number;
	/** Response size in bytes; `0` when the log recorded `-`. */
	bytes: number;
}

/**
 * Matches a CLF line:
 *   <ip> <ident> <user> [<time>] "<method> <path> [protocol]" <status> <bytes>
 *
 * `ident`/`user` are skipped (groups 2–3), and the optional protocol after the
 * path is ignored. `bytes` is a number or `-`.
 */
const CLF =
	/^(\S+) \S+ \S+ \[([^\]]+)\] "(\S+) (\S+)(?: [^"]*)?" (\d{3}) (\d+|-)\s*$/;

/**
 * Parse a single CLF line.
 *
 * Returns a {@link LogEntry} on success, or `null` when the line does not
 * match the expected shape (e.g. blank lines or malformed entries), so callers
 * can skip them without throwing.
 */
export function parse(line: string): LogEntry | null {
	const m = CLF.exec(line);
	if (!m) return null;
	const [, ip, time, method, path, status, bytes] = m;
	return {
		ip,
		time,
		method,
		path,
		status: Number(status),
		bytes: bytes === "-" ? 0 : Number(bytes),
	};
}

/**
 * Three-letter month abbreviation → month number (1–12), for CLF timestamps.
 */
const CLF_MONTHS: Record<string, number> = {
	Jan: 1,
	Feb: 2,
	Mar: 3,
	Apr: 4,
	May: 5,
	Jun: 6,
	Jul: 7,
	Aug: 8,
	Sep: 9,
	Oct: 10,
	Nov: 11,
	Dec: 12,
};

/**
 * Matches a CLF timestamp such as `10/Oct/2000:13:55:36 -0700`.
 */
const CLF_TIME =
	/^(\d{1,2})\/([A-Za-z]{3})\/(\d{4}):(\d{2}):(\d{2}):(\d{2}) ([+-])(\d{2})(\d{2})$/;

/**
 * Convert a CLF timestamp (e.g. `10/Oct/2000:13:55:36 -0700`) to epoch
 * milliseconds, honoring the embedded UTC offset. Returns `null` when the
 * string is not a valid CLF timestamp.
 */
export function clfTimeToMs(time: string): number | null {
	const m = CLF_TIME.exec(time);
	if (!m) return null;
	const [, day, mon, year, hh, mm, ss, sign, tzH, tzM] = m;
	const month = CLF_MONTHS[mon];
	if (!month) return null;
	// Re-shape into ISO 8601 so Date.parse handles the timezone offset.
	const iso = `${year}-${String(month).padStart(2, "0")}-${day.padStart(2, "0")}T${hh}:${mm}:${ss}${sign}${tzH}:${tzM}`;
	const ms = Date.parse(iso);
	return Number.isNaN(ms) ? null : ms;
}

{
  "name": "logstat",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Summarize web server access logs (Common Log Format)",
  "engines": {
    "node": ">=22.6"
  },
  "scripts": {
    "test": "NODE_OPTIONS=--experimental-strip-types node --test tests/",
    "gen": "node --experimental-strip-types scripts/gen.ts"
  }
}

#!/usr/bin/env node
/**
 * Generate a large, deterministic Common Log Format fixture.
 *
 * Writes fixtures/big.log with 100,000 CLF lines drawn from a seeded PRNG.
 * Because the seed is fixed, every run produces a byte-identical file — handy
 * for tests and for diffing output across runs.
 *
 * The distribution is intentionally skewed so `--top N` is meaningful: a
 * Zipf-weighted set of "hot" base paths (clear top-N leaders) plus a small
 * share of near-unique long-tail paths, a range of status codes (200-heavy),
 * and response sizes that are usually small and occasionally large.
 *
 * Usage: node scripts/gen.ts   (or: npm run gen)
 */

import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// --- Config (fixed → deterministic) ----------------------------------------
const SEED = 0x5eed;
const LINES = 100_000;

// --- Seeded PRNG (mulberry32): fast, fully deterministic per 32-bit seed ----
function mulberry32(seed: number): () => number {
	let a = seed >>> 0;
	return () => {
		let t = (a += 0x6d2b79f5) | 0;
		t = Math.imul(t ^ (t >>> 15), t | 1);
		t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
		return ((t ^ (t >>> 14)) >>> 0) / 0x100000000;
	};
}
const rand = mulberry32(SEED);
const randInt = (min: number, max: number): number =>
	min + Math.floor(rand() * (max - min + 1));
const pick = <T>(arr: readonly T[]): T => arr[Math.floor(rand() * arr.length)];

// --- Value pools ------------------------------------------------------------
// Base paths, Zipf-weighted by index (index 0 is the hottest). This produces
// a clear ranking so `--top N` surfaces the most frequent paths.
const BASE_PATHS = [
	"/",
	"/index.html",
	"/api/orders",
	"/api/users",
	"/products",
	"/search",
	"/cart",
	"/checkout",
	"/login",
	"/about",
	"/blog",
	"/docs",
	"/images/logo.png",
	"/css/site.css",
	"/js/app.js",
	"/assets/bundle.js",
	"/assets/main.css",
	"/favicon.ico",
	"/robots.txt",
	"/sitemap.xml",
	"/healthz",
	"/metrics",
] as const;

// GET-heavy, like a real web log.
const METHODS = [
	"GET",
	"GET",
	"GET",
	"GET",
	"POST",
	"PUT",
	"DELETE",
	"HEAD",
	"OPTIONS",
] as const;

// 200-heavy, but covers redirects and common errors too.
const STATUSES = [
	200, 200, 200, 200, 200, 200, 200, 200, 200, 200,
	200, 200, 200, 200, 200, 200, 200, 200, 200, 200,
	201, 204,
	301, 302, 304,
	400, 401, 403, 404, 404, 405,
	500, 502, 503,
] as const;

const LONG_TAIL_KINDS = ["item", "article", "download", "page"] as const;

const pathWeights = BASE_PATHS.map((_, i) => 1 / (i + 1));
const pathTotal = pathWeights.reduce((sum, w) => sum + w, 0);

function pickPath(): string {
	// ~5% long tail: a near-unique resource, so most of these are one-offs.
	if (rand() < 0.05) {
		const kind = pick(LONG_TAIL_KINDS);
		return `/${kind}/${randInt(1, 99_999)}`;
	}
	// Otherwise a base path, Zipf-weighted (index 0 hottest).
	let x = rand() * pathTotal;
	for (let i = 0; i < pathWeights.length; i++) {
		x -= pathWeights[i];
		if (x <= 0) return BASE_PATHS[i];
	}
	return BASE_PATHS[BASE_PATHS.length - 1];
}

function randomIp(): string {
	return `${randInt(1, 254)}.${randInt(0, 255)}.${randInt(0, 255)}.${randInt(1, 254)}`;
}

// Skewed small: most responses are small, a few are large.
function randomBytes(status: number): string {
	if (status === 304) return "-"; // Not Modified → no body
	if (rand() < 0.02) return "-"; // occasionally empty/unknown
	return String(Math.floor(Math.pow(rand(), 2.5) * 200_000));
}

// --- Timestamps (UTC getters → identical across machines/timezones) ---------
const MONTHS = [
	"Jan", "Feb", "Mar", "Apr", "May", "Jun",
	"Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
] as const;
const START = Date.UTC(2024, 0, 1) / 1000; // fixed epoch, seconds

function formatTime(epochSec: number): string {
	const d = new Date(epochSec * 1000);
	const pad = (n: number) => String(n).padStart(2, "0");
	return (
		`${d.getUTCDate()}/${MONTHS[d.getUTCMonth()]}/${d.getUTCFullYear()}:` +
		`${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())} +0000`
	);
}

// --- Generate ---------------------------------------------------------------
const here = dirname(fileURLToPath(import.meta.url));
const OUTPUT = join(here, "..", "fixtures", "big.log");

const lines = new Array<string>(LINES);
let t = START;
for (let i = 0; i < LINES; i++) {
	t += randInt(0, 2); // roughly chronological
	const status = pick(STATUSES);
	lines[i] =
		`${randomIp()} - - [${formatTime(t)}] ` +
		`"${pick(METHODS)} ${pickPath()} HTTP/1.1" ${status} ${randomBytes(status)}`;
}

const output = lines.join("\n") + "\n";
writeFileSync(OUTPUT, output);
console.log(`wrote ${LINES} lines to ${OUTPUT} (${output.length} chars)`);

