test("filterSince: empty input yields empty output", () => {
  assert.deepEqual(filterSince([], Date.parse("2024-01-01")), []);
});

// --- renderTable ---

test("renderTable: produces aligned, equal-width lines", () => {
  const out = renderTable(
    ["status", "count"],
    [
      ["200", "90000"],
      ["404", "56"],
    ],
  );
  const lines = out.split("\n");
  assert.equal(lines.length, 3);
  // "Aligned columns" means every row is the same width.
  const width = lines[0].length;
  for (const line of lines) assert.equal(line.length, width);
  // Header first; labels left-aligned, counts right-aligned.
  assert.ok(lines[0].startsWith("status"));
  assert.ok(lines[0].endsWith("count"));
  assert.ok(lines[1].startsWith("200"));
  assert.ok(lines[1].endsWith("90000"));
  assert.ok(lines[2].startsWith("404"));
  assert.ok(lines[2].endsWith("56"));
});

test("renderTable: uses a two-space gutter for the header", () => {
  assert.equal(renderTable(["status", "count"], []), "status  count");
});

test("renderTable: right-aligns a narrow count under a wide one", () => {
  const out = renderTable(
    ["path", "count"],
    [
      ["/a", "5"],
      ["bb", "100"],
    ],
  );
  const lines = out.split("\n");
  // Both data rows end with their count (right edge aligned).
  assert.ok(lines[1].endsWith("5"));
  assert.ok(lines[2].endsWith("100"));
  // The wider count starts further left than the narrower one.
  assert.ok(lines[2].lastIndexOf("100") < lines[1].lastIndexOf("5"));
});

// --- renderSummary ---

test("renderSummary: emits status table, path table, and skipped line", () => {
  const out = renderSummary({ 200: 3, 404: 1 }, { "/a": 2, "/b": 1 }, 2);
  assert.ok(out.startsWith("status"));
  assert.ok(out.includes("\n\npath"));
  assert.ok(out.endsWith("skipped: 2"));
});

test("renderSummary: shows only the path header when there are no paths", () => {
  const out = renderSummary({ 200: 1 }, {}, 0);
  assert.ok(out.startsWith("status"));
  assert.ok(out.includes("path  count"));
  assert.ok(out.endsWith("skipped: 0"));
});

