#!/usr/bin/env node
/**
 * logstat command-line entry point.
 *
 * Reads a Common Log Format access log and prints the per-status and per-path
 * request counts, plus how many malformed lines were skipped, on stdout.
 *
 * Output is JSON by default; `--format table` prints aligned columns instead.
 *
 * Usage:
 *   node --experimental-strip-types src/cli.ts [--top N] [--since <ISO date>] [--format json|table] <access.log>
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { parse, clfTimeToMs } from "./parse.ts";
import type { LogEntry } from "./parse.ts";
import { countByStatus, countByPath } from "./stats.ts";

export interface ParsedArgs {
  /** Path to the access log, or `null` when none was given. */
  file: string | null;
  /** Max number of paths to keep, or `null` when `--top` was not given. */
  top: number | null;
  /** The raw `--since` ISO date, or `null` when not given. */
  since: string | null;
  /** Output format: `json` (default) or `table`. */
  format: "json" | "table";
  /** Usage-error message, or `null` when the arguments are valid. */
  error: string | null;
}

/**
 * Parse `logstat` arguments (everything after the script name).
 *
 * `--top` may appear before or after the positional file argument. Returns a
 * {@link ParsedArgs} with `error` set on the first problem, without throwing.
 */
export function parseArgs(argv: string[]): ParsedArgs {
  const result: ParsedArgs = { file: null, top: null, since: null, format: "json", error: null };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--top") {
      const value = argv[++i];
      if (value === undefined) {
        result.error = "--top requires a value";
        return result;
      }
      const n = Number(value);
      if (!Number.isInteger(n) || n < 0) {
        result.error = `--top expects a non-negative integer, got "${value}"`;
        return result;
      }
      result.top = n;
    } else if (arg === "--since") {
      const value = argv[++i];
      if (value === undefined) {
        result.error = "--since requires a value";
        return result;
      }
      if (Number.isNaN(Date.parse(value))) {
        result.error = `--since expects an ISO date, got "${value}"`;
        return result;
      }
      result.since = value;
    } else if (arg === "--format") {
      const value = argv[++i];
      if (value === undefined) {
        result.error = "--format requires a value (json or table)";
        return result;
      }
      if (value !== "json" && value !== "table") {
        result.error = `--format must be "json" or "table", got "${value}"`;
        return result;
      }
      result.format = value;
    } else if (arg.startsWith("--")) {
      result.error = `unknown option "${arg}"`;
      return result;
    } else if (result.file === null) {
      result.file = arg;
    } else {
      result.error = `unexpected argument "${arg}"`;
      return result;
    }
  }
  return result;
}

export interface Summary {
  /** Request counts per HTTP status code. */
  status: Record<number, number>;
  /** Request counts per path (optionally trimmed to the top N). */
  path: Record<string, number>;
}

/**
 * Build the summary from parsed entries.
 *
 * When `top` is not `null`, `path` is trimmed to the `top` most frequent
 * paths, relying on {@link countByPath}'s count-descending order.
 */
export function summarize(entries: LogEntry[], top: number | null): Summary {
  let path = countByPath(entries);
  if (top !== null) path = Object.fromEntries(Object.entries(path).slice(0, top));
  return { status: countByStatus(entries), path };
}

/**
 * Keep only the entries whose CLF timestamp is at or after `sinceMs`
 * (epoch milliseconds). Used to implement `--since`.
 */
export function filterSince(entries: LogEntry[], sinceMs: number): LogEntry[] {
  return entries.filter((e) => {
    const ms = clfTimeToMs(e.time);
    return ms !== null && ms >= sinceMs;
  });
}

/**
 * Parse many raw log lines into entries.
 *
 * Blank lines are ignored. Non-blank lines that {@link parse} cannot match are
 * skipped and counted in `skipped`, so a few malformed lines in the middle of
 * a log never abort the run.
 */
export function parseLines(lines: string[]): { entries: LogEntry[]; skipped: number } {
  const entries: LogEntry[] = [];
  let skipped = 0;
  for (const line of lines) {
    if (line.trim() === "") continue;
    const entry = parse(line);
    if (entry === null) skipped++;
    else entries.push(entry);
  }
  return { entries, skipped };
}

/**
 * Render a two-column text table with aligned columns.
 *
 * `head` is the header row and `rows` are the data rows, each a `[left, right]`
 * pair of cell strings. The left column is left-aligned and the right column is
 * right-aligned, separated by a two-space gutter. Returns the rows joined by
 * newlines (no trailing newline).
 */
export function renderTable(
  head: readonly [string, string],
  rows: ReadonlyArray<readonly [string, string]>,
): string {
  const all: ReadonlyArray<readonly [string, string]> = [head, ...rows];
  const leftW = Math.max(...all.map((cell) => cell[0].length));
  const rightW = Math.max(...all.map((cell) => cell[1].length));
  return all
    .map((cell) => `${cell[0].padEnd(leftW)}  ${cell[1].padStart(rightW)}`)
    .join("\n");
}

/**
 * Render the whole summary as aligned columns (for `--format table`): a status
 * table, a path table, and a `skipped` line, separated by blank lines.
 */
export function renderSummary(
  status: Record<number, number>,
  path: Record<string, number>,
  skipped: number,
): string {
  const statusRows: [string, string][] = Object.entries(status).map(
    ([k, v]): [string, string] => [k, String(v)],
  );
  const pathRows: [string, string][] = Object.entries(path).map(
    ([k, v]): [string, string] => [k, String(v)],
  );
  return [
    renderTable(["status", "count"], statusRows),
    renderTable(["path", "count"], pathRows),
    `skipped: ${skipped}`,
  ].join("\n\n");
}

function main(): void {
  const { file, top, since, format, error } = parseArgs(process.argv.slice(2));
  if (error) {
    process.stderr.write(`logstat: ${error}\n`);
    process.exitCode = 1;
    return;
  }
  if (file === null) {
    process.stderr.write("usage: node --experimental-strip-types src/cli.ts [--top N] [--since <ISO date>] [--format json|table] <access.log>\n");
    process.exitCode = 1;
    return;
  }

  let raw: string;
  try {
    raw = readFileSync(file, "utf8");
  } catch (err) {
    process.stderr.write(`logstat: cannot read ${file}: ${(err as Error).message}\n`);
    process.exitCode = 1;
    return;
  }

  const parsed = parseLines(raw.split("\n"));
  const skipped = parsed.skipped;
  let entries = parsed.entries;
  if (since !== null) {
    entries = filterSince(entries, Date.parse(since));
  }
  const summary = summarize(entries, top);
  if (format === "table") {
    process.stdout.write(`${renderSummary(summary.status, summary.path, skipped)}\n`);
  } else {
    const output = { status: summary.status, path: summary.path, skipped };
    process.stdout.write(`${JSON.stringify(output, null, 2)}\n`);
  }
}

